<div class="modal-welcome"><strong>Parceria CAB + Raven</strong><button type="button" id="fechar-pre-cadastro">Fechar</button></div>
</dialog>
<script>
(()=>{
const confirmacao=document.getElementById('confirmacao');
if (confirmacao && typeof confirmacao.showModal === 'function') confirmacao.showModal();
if (confirmacao?.dataset.abrirWhatsapp === '1') {
    window.location.assign(confirmacao.querySelector('a').href);
}
const perfil=document.querySelector('input[name="tipo_documento"]'),tel=document.getElementById('whatsapp');
const campos=document.getElementById('cadastro-campos'),doc=document.getElementById('documento');
const TIPOS={cpf:{nome:'Nome completo',doc:'CPF',ph:'000.000.000-00',max:14},cnpj:{nome:'Razão social',doc:'CNPJ',ph:'00.000.000/0000-00',max:18}};
const tipoAtual=()=>document.querySelector('input[name="tipo_documento"]:checked');
// Aplica a máscara mantendo o cursor depois do mesmo dígito (edição no meio do campo).
function mascarar(input,formatar) {
    const antes=input.value,pos=input.selectionStart??antes.length;
    const digitosAntes=antes.slice(0,pos).replace(/\D/g,'').length;
    const novo=formatar(antes.replace(/\D/g,''));
    if (novo===antes) return;
    input.value=novo;
    if (document.activeElement!==input) return;
    let c=0,i=0;
    while (i<novo.length && c<digitosAntes) { if (/\d/.test(novo[i])) c++; i++; }
    input.setSelectionRange(i,i);
}
function formatarCpf(n) {
    n=n.slice(0,11);
    return n.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1-$2');
}
function formatarCnpj(n) {
    n=n.slice(0,14);
    return n.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2');
}
function formatarTelefone(n) {
    if (n.length>11 && n.startsWith('55')) n=n.slice(2);
    n=n.slice(0,11);
    if (!n) return '';
    if (n.length<=2) return '('+n;
    const ddd='('+n.slice(0,2)+') ',resto=n.slice(2);
    if (resto.length<=4) return ddd+resto;
    const corte=n.length===11?5:4;
    return ddd+resto.slice(0,corte)+'-'+resto.slice(corte);
}
function mascararDoc() {
    const t=tipoAtual();
    if (!t || !doc) return;
    mascarar(doc,t.value==='cpf'?formatarCpf:formatarCnpj);
}
const CNPJ_URL=@json(url('/cabraven/cnpj'));
const nome=document.getElementById('nome'),docStatus=document.getElementById('documento_status');
let cnpjConsultado='',consulta=null;
function statusDoc(texto,classe) {
    if (!docStatus) return;
    docStatus.textContent=texto||'';
    docStatus.className='doc-status'+(classe?' '+classe:'');
}
function cnpjValido(c) {
    if (!/^\d{14}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
    const dv=n=>{const p=n===12?[5,4,3,2,9,8,7,6,5,4,3,2]:[6,5,4,3,2,9,8,7,6,5,4,3,2];let s=0;for(let i=0;i<n;i++)s+=+c[i]*p[i];const r=s%11;return r<2?0:11-r;};
    return dv(12)===+c[12] && dv(13)===+c[13];
}
function consultarCnpj() {
    const t=tipoAtual();
    if (!t || t.value!=='cnpj') return;
    const cnpj=doc.value.replace(/\D/g,'');
    if (cnpj.length<14) { cnpjConsultado=''; statusDoc(''); return; }
    if (cnpj===cnpjConsultado) return;
    if (!cnpjValido(cnpj)) { cnpjConsultado=''; statusDoc('CNPJ inválido. Confira os números digitados.','erro'); return; }
    cnpjConsultado=cnpj;
    if (consulta) consulta.abort();
    consulta=new AbortController();
    statusDoc('Consultando a Receita Federal…');
    nome.classList.add('carregando');
    fetch(CNPJ_URL+'/'+cnpj,{headers:{Accept:'application/json'},signal:consulta.signal})
        .then(r=>r.json().then(dados=>({ok:r.ok,dados})))
        .then(({ok,dados})=>{
            if (doc.value.replace(/\D/g,'')!==cnpj) return;
            if (!ok) { statusDoc((dados&&dados.message?dados.message:'Não foi possível consultar o CNPJ.')+' Preencha a razão social.','erro'); return; }
            nome.value=dados.razao_social;
            const situacao=dados.situacao && dados.situacao!=='ATIVA' ? ' Situação na Receita: '+dados.situacao+'.' : '';
            statusDoc('Razão social preenchida com os dados da Receita Federal.'+situacao,situacao?'erro':'ok');
        })
        .catch(e=>{ if (e.name!=='AbortError') statusDoc('Não foi possível consultar o CNPJ agora. Preencha a razão social.','erro'); })
        .finally(()=>nome.classList.remove('carregando'));
}
function aplicarTipo() {
    if (!campos) return;
    const t=tipoAtual();
    campos.hidden=!t;
    if (!t) return;
    const c=TIPOS[t.value];
    document.getElementById('nome_label').textContent=c.nome;
    document.getElementById('documento_label').textContent=c.doc;
    doc.placeholder=c.ph;
    doc.maxLength=c.max;
    cnpjConsultado='';
    statusDoc('');
    mascararDoc();
}
document.querySelectorAll('input[name="tipo_documento"]').forEach(radio=>radio.addEventListener('change',()=>{
    aplicarTipo();
    doc.focus();
}));
if (doc) doc.addEventListener('input',()=>{ mascararDoc(); consultarCnpj(); });
aplicarTipo();

const modal=document.getElementById('pre-cadastro-modal');
const card=document.getElementById('cadastro-card');
const formHome=card.parentNode;
function abrirCadastro() {
    if (perfil && typeof modal.showModal === 'function') {
        modal.append(card);
        modal.showModal();
        perfil.focus({preventScroll:true});
        return;
    }
    document.getElementById('cadastro').scrollIntoView();
    if (perfil) perfil.focus({preventScroll:true});
}
document.getElementById('fechar-pre-cadastro').addEventListener('click',()=>modal.close());
modal.addEventListener('close',()=>formHome.append(card));
document.querySelectorAll('[data-abrir-cadastro]').forEach(link=>{
    link.addEventListener('click',event=>{
        if (!perfil || typeof modal.showModal !== 'function') return;
        event.preventDefault();
        abrirCadastro();
    });
});
if (perfil && card.querySelector('.alert')) abrirCadastro();
if(tel){tel.addEventListener('input',()=>mascarar(tel,formatarTelefone));mascarar(tel,formatarTelefone);}

})();
</script></body></html>
